// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz parameters: amount to send and a caller's private key (so we can vm.prank an EOA)
    function testFuzz_property(uint256 amount, uint256 pk) public {
        vm.assume(amount <= VALUE_CAP);
        pk = bound(pk, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amount in a wide but relevant domain
        // we want to allow the fuzzer to pick amount == 10 ether among others
        vm.assume(amount <= 100 ether);

        address caller = vm.addr(pk);
        vm.deal(caller, amount + 1 ether);

        // record previous pastBlockTime
        uint256 prev = c.pastBlockTime();

        bool ok;
        // perform the call as the fuzzed caller; use low-level try/catch pattern via bytes call
        vm.prank(caller);
        // call fallback by sending value with empty calldata; use (bool success, ) = address(c).call{value: amount}("");
        // But per HARD RULE: for a revert difference, wrap the boundary call in try c.fallback... pattern
        // However direct try on fallback identifier caused prior compile error; so use try/catch on a call to address(c).call
        // We capture success via low-level call and set ok accordingly.
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        // The general property: when amount == 10 ether, the reference C accepts the call (ok == true)
        // and updates pastBlockTime to be > prev. We assert accept condition (which the reference always satisfies)
        // This single assertion will fail on the mutant when amount == 10 ether because mutant requires != 10 ether
        if (amount == 10 ether) {
            // ensure the call succeeded on the reference and state was updated
            // read pastBlockTime getter (public)
            uint256 after_ = c.pastBlockTime();
            assertTrue(ok && after_ > prev);
        } else {
            // for other amounts, we just assert true to avoid excluding inputs; keep test wide
            assertTrue(true);
        }
    }
}
